import { createPlayer, type PlaybackAdapter } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { For, merge, Show } from "solid-js";

import { t } from "./theme.ts" with { type: "cssints" };

export interface PlayerProps {
  /** The playback engine: the primitive drives it and never imports a media library. */
  readonly adapter: PlaybackAdapter;
  /** The media the adapter opens; the `<video>` shows the same source when the kind is `"video"`. */
  readonly src?: string | undefined;
  /** A video frame, or an audio bar. @default "video" */
  readonly kind?: "video" | "audio" | undefined;
  /** The surface's accessible name: what is playing. @default "Media player" */
  readonly label?: string | undefined;
  /** The line an audio bar shows; left out, the label. */
  readonly title?: string | undefined;
  /** A video's first frame, before anything is decoded: a URL or a `data:` URI. */
  readonly poster?: string | undefined;
  /** The video frame's shape in CSS, so the page picks the crop. @default "16 / 9" */
  readonly aspect?: string | undefined;
  /** The volume at mount, 0..100 (uncontrolled). @default 100 */
  readonly defaultVolume?: number | undefined;
  /** Muted at mount (uncontrolled). @default false */
  readonly defaultMuted?: boolean | undefined;
  /** The line under the player; left out, the keys in one sentence. */
  readonly hint?: string | undefined;
  readonly class?: string | undefined;
}

const DEFAULT_LABEL = "Media player";
const DEFAULT_ASPECT = "16 / 9";

const DEFAULT_HINT =
  "Space or K plays and pauses, the arrows seek five seconds and M mutes; on the seek slider the arrows move one second, Page Up and Page Down fifteen, Home and End jump.";

// The frame is the surface: the media sits at the top and the bar under it, and the radius and the border are the kit's.
const frameClass = css.cn(
  css.display("flex"),
  css.flexDirection("column"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.color(t.color.text),
  css.bg(t.color.surface),
  css.border("1px solid", t.color.border),
  css.borderRadius(t.radius.xl),
  css.fontSize(t.font.size),
);

// The stage is the focusable surface the primitive's keys land on: the video frame or the audio bar, with the ring the kit
// paints, inset so the frame's rounded corners do not clip it.
const stageClass = css.cn(
  css.position("relative"),
  css.display("block"),
  css.width("100%"),
  css.overflow("hidden"),
  css.boxSizing("border-box"),
  css.bg(t.color.page),
  css.outline("none"),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("-2px")),
);

// The picture fills the stage and keeps its shape: a portrait video crops rather than squashing the frame's ratio.
const mediaClass = css.cn(
  css.display("block"),
  css.width("100%"),
  css.height("100%"),
  css.objectFit("cover"),
);

const audioClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._3),
  css.minHeight(t.space._10),
  css.padding(t.space._2, t.space._3),
  css.boxSizing("border-box"),
);

const waveClass = css.cn(
  css.display("inline-flex"),
  css.alignItems("flex-end"),
  css.gap("2px"),
  css.height(t.space._6),
  css.flexShrink("0"),
);

const barMarkClass = css.cn(css.width("3px"), css.borderRadius("999px"), css.bg(t.color.highlight));

const audioTitleClass = css.cn(
  css.overflow("hidden"),
  css.whiteSpace("nowrap"),
  css.textOverflow("ellipsis"),
  css.fontWeight("500"),
);

const barClass = css.cn(
  css.display("flex"),
  css.alignItems("center"),
  css.gap(t.space._2),
  css.padding(t.space._2, t.space._3),
);

// A button of the control bar. The transition is the skin's, and only for a reader who allows motion.
const buttonClass = css.cn(
  css.appearance("none"),
  css.display("inline-flex"),
  css.alignItems("center"),
  css.justifyContent("center"),
  css.height(t.space._8),
  css.minWidth(t.space._8),
  css.margin("0"),
  css.padding("0", t.space._2),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
  css.color(t.color.text),
  css.fontSize(t.font.sizeSm),
  css.lineHeight(1),
  css.cursor("pointer"),
  css.hover(css.bg(t.color.buttonBackgroundPressed), css.borderColor(t.color.borderHover)),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
  css.media("(prefers-reduced-motion: no-preference)")(
    css.transition("background-color 120ms ease-out, border-color 120ms ease-out"),
  ),
);

// The mute toggle's look reads its pressed state, which the primitive announces: the skin paints `aria-pressed`.
const muteButtonClass = css.cn(
  buttonClass,
  css.attr("aria-pressed", "true")(
    css.bg(t.color.buttonBackgroundPressed),
    css.borderColor(t.color.borderHover),
  ),
);

const timeClass = css.cn(
  css.fontSize(t.font.sizeSm),
  css.color(t.color.text),
  css.fontVariantNumeric("tabular-nums"),
  css.whiteSpace("nowrap"),
);

const seekClass = css.cn(
  css.position("relative"),
  css.display("flex"),
  css.alignItems("center"),
  css.flex("1"),
  css.minWidth("0"),
  css.height(t.space._7),
  css.margin("0"),
  css.padding("0"),
  css.outline("none"),
  css.cursor("pointer"),
  css.borderRadius(t.radius.sm),
  css.focusVisible(css.outline("2px solid", t.color.focusRing), css.outlineOffset("2px")),
);

// The rail sits on the slider's middle line and clips the fill; the thumb overflows it, so it is the slider's own child.
const railClass = css.cn(
  css.position("absolute"),
  css.left("0"),
  css.right("0"),
  css.top("50%"),
  css.height(t.space._1),
  css.transform("translateY(-50%)"),
  css.overflow("hidden"),
  css.borderRadius("999px"),
  css.bg(t.color.buttonBackground),
);

// The fill is the skin's, and the width is set inline from the primitive's `aria-valuenow` and `aria-valuemax`. The
// transition follows a seek; the motion preference turns it off.
const fillClass = css.cn(
  css.height("100%"),
  css.bg(t.color.highlight),
  css.borderRadius("999px"),
  css.media("(prefers-reduced-motion: no-preference)")(css.transition("width 160ms linear")),
);

const thumbClass = css.cn(
  css.position("absolute"),
  css.top("50%"),
  css.width(t.space._3),
  css.height(t.space._3),
  css.transform("translate(-50%, -50%)"),
  css.boxSizing("border-box"),
  css.border("1px solid", t.color.border),
  css.borderRadius("999px"),
  css.bg(t.color.surface),
);

const hintClass = css.cn(css.margin("0"), css.fontSize(t.font.sizeSm), css.color(t.color.muted));

/** `m:ss`, the primitive's own `aria-valuetext` format: the time line and the slider cannot disagree. */
const mss = (seconds: number): string =>
  `${Math.floor(seconds / 60)}:${String(Math.floor(seconds) % 60).padStart(2, "0")}`;

/** The audio bar's drawn waveform: percentages of the bar's height, so the shape is the fixture data's. */
const AUDIO_BARS = [35, 70, 45, 90, 60, 30, 75, 50, 85, 40, 65, 25] as const;

/**
 * A media player, styled: `createPlayer` owns the playback stage, the position and the duration, the seek's `role="slider"`
 * with its `aria-value*` and its keys, the play/pause label, the mute toggle's `aria-pressed`, the four preferences and the
 * surface keys (Space / K, the arrows, M, F). The adapter is the caller's, so the primitive never imports a media library.
 *
 * The skin owns the surface (a video frame or an audio bar), the frame's radius, border and tokens in light and dark, the
 * control bar, the seek's rail, fill and thumb, the time line, and the reduced-motion rules. It does not call the `<video>`
 * element's own playback: the adapter decodes, and the element is the picture frame (`preload="none"`, the caller's
 * `poster`). A page whose adapter paints elsewhere passes its own surface. Fullscreen is the primitive's state only, since
 * a page may fullscreen a container the skin does not own.
 */
export const Player = (props: PlayerProps): JSX.Element => {
  const player = createPlayer({
    adapter: props.adapter,
    get src() {
      return props.src;
    },
    defaultVolume: props.defaultVolume,
    defaultMuted: props.defaultMuted,
  });

  // The time, the fill and the thumb all read the primitive's ARIA, so a seek and a playback tick cannot drift apart.
  const now = (): number => player.seekProps["aria-valuenow"];
  const total = (): number => player.seekProps["aria-valuemax"];
  const percent = (): number => (total() <= 0 ? 0 : (now() / total()) * 100);

  // The glyph reads the same state the button's name does, so the two cannot disagree.
  const active = (): boolean => player.playProps["aria-label"] === "Pause";

  let seekElement: HTMLDivElement | undefined;

  // A press on the rail seeks to that point. ponytail: no drag is wired; add pointermove + setPointerCapture when a page
  // asks to scrub, and throttle it to the frame.
  const seekAt = (event: PointerEvent): void => {
    const box = seekElement?.getBoundingClientRect();
    if (box === undefined || box.width <= 0 || total() <= 0) {
      return;
    }
    const fraction = (event.clientX - box.left) / box.width;
    player.seek(fraction * total());
  };

  const surface = merge(player.surfaceProps, {
    role: "group" as const,
    get "aria-label"() {
      return props.label ?? DEFAULT_LABEL;
    },
    "data-part": "player-surface",
    get class() {
      return stageClass;
    },
  });

  const play = merge(player.playProps, {
    "data-part": "player-play",
    get class() {
      return buttonClass;
    },
  });

  const seek = merge(player.seekProps, {
    "aria-label": "Seek",
    "data-part": "player-seek",
    get class() {
      return seekClass;
    },
    onPointerDown: seekAt,
  });

  const mute = merge(player.muteProps, {
    "data-part": "player-mute",
    get class() {
      return muteButtonClass;
    },
  });

  return (
    <div data-part="player" class={css.cn(frameClass, props.class)}>
      <div
        {...surface}
        style={props.kind === "audio" ? {} : { "aspect-ratio": props.aspect ?? DEFAULT_ASPECT }}
      >
        <Show
          when={props.kind === "audio"}
          fallback={
            <video
              data-part="player-media"
              src={props.src}
              poster={props.poster}
              preload="none"
              playsinline
              aria-hidden="true"
              class={mediaClass}
            />
          }
        >
          <div data-part="player-audio" class={audioClass}>
            <span aria-hidden="true" class={waveClass}>
              <For each={AUDIO_BARS}>
                {(height) => <span class={barMarkClass} style={{ height: `${height}%` }} />}
              </For>
            </span>
            <span class={audioTitleClass}>{props.title ?? props.label ?? DEFAULT_LABEL}</span>
          </div>
        </Show>
      </div>
      <div data-part="player-bar" class={barClass}>
        <button {...play}>
          <span aria-hidden="true">{active() ? "❚❚" : "▶"}</span>
        </button>
        <span data-part="player-time" class={timeClass}>
          {`${mss(now())} / ${mss(total())}`}
        </span>
        <div
          {...seek}
          ref={(element: HTMLDivElement) => {
            seekElement = element;
          }}
        >
          <div aria-hidden="true" class={railClass}>
            <div data-part="player-fill" class={fillClass} style={{ width: `${percent()}%` }} />
          </div>
          <span
            aria-hidden="true"
            data-part="player-thumb"
            class={thumbClass}
            style={{ left: `${percent()}%` }}
          />
        </div>
        <button {...mute}>Mute</button>
      </div>
      <p data-part="player-hint" class={hintClass}>
        {props.hint ?? DEFAULT_HINT}
      </p>
    </div>
  );
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import type { PlaybackAdapter, PlaybackAdapterEvent } from "@cssints/headless";
import { render } from "@solidjs/web";
import type { JSX } from "@solidjs/web";

import { Player } from "./player.tsx";

/** The demo's made-up duration: 1:30, so the time line reads long enough to see the minutes. */
export const PLAYER_DURATION = 90;

/** The demo's source. Nothing fetches it: the adapter is fake and the `<video>` loads no data. */
export const PLAYER_SOURCE = "demo/coast-at-dusk.mp4";

/** The video frame's shape: 3:2, as the demo's drawing is. */
export const PLAYER_ASPECT = "3 / 2";

/** The demo's drawn frame, an inline SVG: the example needs no image file and no network. */
const POSTER = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 400"><defs><linearGradient id="sky" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2f4a63"/><stop offset=".55" stop-color="#c98d63"/><stop offset="1" stop-color="#f3d9b0"/></linearGradient></defs><rect width="600" height="400" fill="url(#sky)"/><circle cx="430" cy="150" r="46" fill="#fff3d6"/><path d="M0 280 Q120 220 260 275 T600 265 V400 H0Z" fill="#20364a"/><path d="M0 320 Q160 285 320 320 T600 315 V400 H0Z" fill="#16273a" opacity=".8"/></svg>`;

export const PLAYER_POSTER = `data:image/svg+xml,${encodeURIComponent(POSTER)}`;

/**
 * The demo's adapter: a `PlaybackAdapter` with no file behind it. It announces the duration at load, runs a clock while
 * playing (one tick every 200 ms) so Play visibly advances the seek and the time, and records every committed seek, which
 * is what the browser test reads: it drives the adapter the way the primitive's own oracle does, through the controls.
 */
export class DemoPlaybackAdapter implements PlaybackAdapter {
  /** Every commit the primitive handed over, in seconds. */
  readonly seeks: number[] = [];

  private readonly listeners = new Set<(event: PlaybackAdapterEvent) => void>();
  private readonly duration: number;
  private position = 0;
  private ticker: ReturnType<typeof setInterval> | undefined;
  private reachedEnd = false;

  constructor(duration = PLAYER_DURATION) {
    this.duration = duration;
  }

  load(): Promise<void> {
    this.emit({ type: "loadedmetadata", duration: this.duration });
    this.emit({ type: "canplay" });
    return Promise.resolve();
  }

  play(): Promise<void> {
    // a play after the end starts the film again, as the primitive's position does
    if (this.reachedEnd) {
      this.position = 0;
      this.reachedEnd = false;
    }
    this.startClock();
    return Promise.resolve();
  }

  pause(): void {
    this.stopClock();
  }

  seek(seconds: number): Promise<void> {
    this.seeks.push(seconds);
    this.position = Math.min(this.duration, Math.max(0, seconds));
    this.reachedEnd = false;
    this.emit({ type: "seeking" });
    this.emit({ type: "seeked" });
    return Promise.resolve();
  }

  setVolume(): void {
    // the demo plays no sound; the primitive's gain lands here and is dropped on purpose
  }

  setPlaybackRate(): void {}

  dispose(): void {
    this.stopClock();
    this.listeners.clear();
  }

  subscribe(listener: (event: PlaybackAdapterEvent) => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  private startClock(): void {
    this.stopClock();
    this.ticker = setInterval(() => this.tick(), 200);
  }

  private stopClock(): void {
    if (this.ticker !== undefined) {
      clearInterval(this.ticker);
      this.ticker = undefined;
    }
  }

  private tick(): void {
    this.position = Math.min(this.duration, this.position + 0.2);
    this.emit({ type: "timeupdate", currentTime: this.position });
    if (this.position >= this.duration) {
      this.reachedEnd = true;
      this.stopClock();
      this.emit({ type: "ended" });
    }
  }

  private emit(event: PlaybackAdapterEvent): void {
    for (const listener of this.listeners) {
      listener(event);
    }
  }
}

export interface PlayerExampleProps {
  readonly class?: string | undefined;
  /** A test passes its own adapter to read what the primitive asked it; the demo's own runs a clock. */
  readonly adapter?: PlaybackAdapter | undefined;
}

/**
 * The starter in ordinary use: a made-up film at a 3:2 frame, the control bar under it, and the sentence about the keys.
 * The adapter is the demo's own, so there is no media file: press Play and the clock moves the seek, the time and the fill.
 * A page copies this and swaps `DemoPlaybackAdapter` for its engine.
 */
export const PlayerExample = (props: PlayerExampleProps): JSX.Element => {
  const adapter = props.adapter ?? new DemoPlaybackAdapter();
  return (
    <Player
      class={props.class}
      adapter={adapter}
      src={PLAYER_SOURCE}
      poster={PLAYER_POSTER}
      aspect={PLAYER_ASPECT}
      label="A short film about the coast"
      title="The coast at dusk"
    />
  );
};

/** What a mounted demo hands the test: where it lives, the adapter it drives, and a teardown. */
export interface MountedPlayer {
  readonly root: HTMLElement;
  readonly adapter: DemoPlaybackAdapter;
  readonly dispose: () => void;
}

/** The demo's width, so the bar has the same room in every test run. */
const DEMO_WIDTH = 480;

/**
 * Mounts the styled player in ordinary use at a 480 px frame. The primitive owns the playback state and the controls'
 * semantics; the fixture is the page's media and its adapter.
 */
export const mountPlayer = (): MountedPlayer => {
  const root = document.createElement("div");
  root.style.width = `${DEMO_WIDTH}px`;
  document.body.append(root);
  const adapter = new DemoPlaybackAdapter();
  const dispose = render(() => <PlayerExample adapter={adapter} />, root);
  return {
    root,
    adapter,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { afterEach, describe, expect, it } from "vite-plus/test";

import { type MountedPlayer, PLAYER_DURATION, mountPlayer } from "./player.fixture";

// @cssints/headless checks `createPlayer` against specs/apg/player.qnt and the ported scenarios. This file is the skin's
// oracle: it mounts the starter in a real Chromium and drives the controls a reader does, through the demo's fake adapter.
// Nothing plays a real file: the adapter announces 1:30 and ticks its own clock.

/** Solid applies setters on the next flush; the primitive loads in `onSettled`, one frame later. */
const settle = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => setTimeout(resolve, 0)));

/** Polls until `done` holds, so the adapter's 200 ms clock is waited for rather than assumed. */
const waitFor = async (done: () => boolean, limit = 4000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await settle();
  }
};

const live: MountedPlayer[] = [];

const mounted = (): MountedPlayer => {
  const instance = mountPlayer();
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

const part = <T extends HTMLElement>(root: ParentNode, name: string): T => {
  const element = root.querySelector<T>(`[data-part="${name}"]`);
  if (element === null) {
    throw new Error(`player: no ${name}`);
  }
  return element;
};

const surface = (root: ParentNode): HTMLElement => part(root, "player-surface");
const play = (root: ParentNode): HTMLButtonElement => part(root, "player-play");
const seek = (root: ParentNode): HTMLElement => part(root, "player-seek");
const time = (root: ParentNode): HTMLElement => part(root, "player-time");
const mute = (root: ParentNode): HTMLButtonElement => part(root, "player-mute");
const fill = (root: ParentNode): HTMLElement => part(root, "player-fill");

const value = (root: ParentNode): number => Number(seek(root).getAttribute("aria-valuenow"));

const click = async (element: HTMLElement): Promise<void> => {
  element.click();
  await settle();
};

/** A key on the focused control, as a reader's would arrive. */
const press = async (target: HTMLElement, key: string): Promise<void> => {
  target.dispatchEvent(new KeyboardEvent("keydown", { key, bubbles: true, cancelable: true }));
  await settle();
};

describe("Player", () => {
  it("is a named group whose surface holds the caller's video frame", async () => {
    const { root } = mounted();
    await settle();

    expect(surface(root).getAttribute("role")).toBe("group");
    expect(surface(root).getAttribute("aria-label")).toBe("A short film about the coast");
    // the primitive's own surface props: the stage is its tab stop and takes its keys
    expect(surface(root).tabIndex).toBe(0);

    const media = part<HTMLVideoElement>(root, "player-media");
    expect(media.tagName).toBe("VIDEO");
    expect(media.getAttribute("src")).toBe("demo/coast-at-dusk.mp4");
    // the adapter decodes; the element is the picture frame, not a second player
    expect(media.getAttribute("preload")).toBe("none");
    expect(media.hasAttribute("controls")).toBe(false);
  });

  it("shows the duration the adapter announced in m:ss, and the slider's value text follows", async () => {
    const { root } = mounted();
    await settle();

    expect(seek(root).getAttribute("aria-valuemax")).toBe(String(PLAYER_DURATION));
    expect(seek(root).getAttribute("aria-valuetext")).toBe("0:00");
    expect(time(root).textContent).toBe("0:00 / 1:30");

    await press(seek(root), "End");
    expect(time(root).textContent).toBe("1:30 / 1:30");
    expect(seek(root).getAttribute("aria-valuetext")).toBe("1:30");

    await press(seek(root), "ArrowLeft");
    expect(time(root).textContent).toBe("1:29 / 1:30");
  });

  it("names the play button from the primitive's stage", async () => {
    const { root } = mounted();
    await settle();

    expect(play(root).getAttribute("aria-label")).toBe("Play");
    await click(play(root));
    expect(play(root).getAttribute("aria-label")).toBe("Pause");
    await click(play(root));
    expect(play(root).getAttribute("aria-label")).toBe("Play");
  });

  it("is the primitive's seek slider, and every key commits to the adapter", async () => {
    const { root, adapter } = mounted();
    await settle();

    expect(seek(root).getAttribute("role")).toBe("slider");
    expect(seek(root).getAttribute("aria-label")).toBe("Seek");
    expect(seek(root).getAttribute("aria-valuemin")).toBe("0");
    expect(seek(root).tabIndex).toBe(0);

    await press(seek(root), "ArrowRight");
    expect(value(root)).toBe(1);
    await press(seek(root), "PageUp");
    expect(value(root)).toBe(16);
    await press(seek(root), "PageDown");
    expect(value(root)).toBe(1);
    await press(seek(root), "Home");
    expect(value(root)).toBe(0);
    await press(seek(root), "End");
    expect(value(root)).toBe(PLAYER_DURATION);

    expect(adapter.seeks).toEqual([1, 16, 1, 0, PLAYER_DURATION]);
  });

  it("advances the slider, the time and the fill from the adapter's clock, and a press on the rail seeks", async () => {
    const { root, adapter } = mounted();
    await settle();

    expect(value(root)).toBe(0);
    expect(fill(root).style.width).toBe("0%");

    await click(play(root));
    await waitFor(() => value(root) >= 1);
    expect(value(root)).toBeGreaterThanOrEqual(1);
    expect(time(root).textContent).not.toBe("0:00 / 1:30");
    expect(parseFloat(fill(root).style.width)).toBeGreaterThan(0);
    expect(parseFloat(part(root, "player-thumb").style.left)).toBeGreaterThan(0);

    // a press in the middle of the rail seeks to the middle of the film
    const box = seek(root).getBoundingClientRect();
    seek(root).dispatchEvent(
      new PointerEvent("pointerdown", {
        clientX: box.left + box.width / 2,
        bubbles: true,
        cancelable: true,
      }),
    );
    await settle();
    expect(Math.abs(value(root) - PLAYER_DURATION / 2)).toBeLessThanOrEqual(1);
    const committed = adapter.seeks.at(-1) ?? 0;
    expect(Math.abs(committed - PLAYER_DURATION / 2)).toBeLessThanOrEqual(1);

    await click(play(root));
    expect(play(root).getAttribute("aria-label")).toBe("Play");
  });

  it("paints mute from the primitive's pressed state, and the surface takes the rest of the keys", async () => {
    const { root } = mounted();
    await settle();

    expect(mute(root).getAttribute("aria-pressed")).toBe("false");
    await click(mute(root));
    expect(mute(root).getAttribute("aria-pressed")).toBe("true");

    // the surface's own keys: the arrows seek five seconds and Space plays
    await press(surface(root), "m");
    expect(mute(root).getAttribute("aria-pressed")).toBe("false");
    await press(surface(root), "ArrowRight");
    expect(value(root)).toBe(5);
    await press(surface(root), " ");
    expect(play(root).getAttribute("aria-label")).toBe("Pause");
    await click(play(root));
    expect(play(root).getAttribute("aria-label")).toBe("Play");
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
